@import "@fontsource-variable/hanken-grotesk";

/* Light (faithful): white bands with warm #f7f7f5 and cool #f3f5f4 off-white bands between,
   #131413 ink for text, buttons and the dark bands, #585a59 warm grey text, and a single
   deep green #1d7d6c for links, list dots and icons, with pale sage #9fc5bc on dark and
   pale green-grey #edf3f0 panels. */
:root {
  --background: #ffffff;
  --foreground: #131413;
  --card: #ffffff;
  --card-foreground: #131413;
  --popover: #ffffff;
  --popover-foreground: #131413;
  --primary: #131413;
  --primary-foreground: #ffffff;
  --secondary: #f7f7f5;
  --secondary-foreground: #2d3130;
  --muted: #f3f5f4;
  --muted-foreground: #585a59;
  --accent: #edf3f0;
  --accent-foreground: #1d7d6c;
  --destructive: #c9452f;
  --destructive-foreground: #ffffff;
  --border: #e9ebea;
  --input: #c9d0ce;
  --ring: #1d7d6c;
  --highlight: #1d7d6c;
  --highlight-foreground: #ffffff;
  --glow: #9fc5bc;
  --chart-1: #1d7d6c;
  --chart-2: #9fc5bc;
  --chart-3: #d9675a;
  --chart-4: #3f86c4;
  --chart-5: #d8a33b;
  --sidebar: #f7f7f5;
  --sidebar-foreground: #2d3130;
  --sidebar-primary: #131413;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #edf3f0;
  --sidebar-accent-foreground: #131413;
  --sidebar-border: #e9ebea;
  --sidebar-ring: #1d7d6c;

  --typeface-body: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.625rem;
  --page-width: 75rem;
  --page-gutter: 1rem;
  --section-y: 8rem;
}

/* Dark sibling, and the palette of the dark bands (hero, header, stat cards, closing band,
   footer), which put the .dark class on themselves: #131413 ink ground, #1b1d1c cards,
   white text and buttons, the same greens lifted so links and icons still read. */
.dark {
  --background: #131413;
  --foreground: #ffffff;
  --card: #1b1d1c;
  --card-foreground: #ffffff;
  --popover: #1b1d1c;
  --popover-foreground: #ffffff;
  --primary: #ffffff;
  --primary-foreground: #131413;
  --secondary: #171918;
  --secondary-foreground: #e3e7e5;
  --muted: #161817;
  --muted-foreground: #a3a8a6;
  --accent: #1a2622;
  --accent-foreground: #5cc2ab;
  --destructive: #e8735f;
  --destructive-foreground: #131413;
  --border: #2a2e2c;
  --input: #3a413e;
  --ring: #5cc2ab;
  --highlight: #5cc2ab;
  --highlight-foreground: #131413;
  --glow: #9fc5bc;
  --chart-1: #5cc2ab;
  --chart-2: #9fc5bc;
  --chart-3: #ea8576;
  --chart-4: #6aa8de;
  --chart-5: #e6b75a;
  --sidebar: #171918;
  --sidebar-foreground: #e3e7e5;
  --sidebar-primary: #5cc2ab;
  --sidebar-primary-foreground: #131413;
  --sidebar-accent: #1a2622;
  --sidebar-accent-foreground: #ffffff;
  --sidebar-border: #2a2e2c;
  --sidebar-ring: #5cc2ab;
}
